WITH SupplierStats AS (SELECT supplier_id, SUM(CASE WHEN category = 'Home' THEN 1 ELSE 0 END) AS home_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values FROM products WHERE stock_qty = 248 GROUP BY supplier_id) SELECT s.rating, S.home_count, S.brand_values FROM suppliers s LEFT JOIN SupplierStats S ON s.id = S.supplier_id WHERE S.home_count >= 45 ORDER BY rating;
